using System;
using DebugLogger;
using Newtonsoft.Json;
using System.Data;
using MagicSqlConnector;
// using System.Data.SqlClient; // SqlDataAdapter BUT only MS SQL Server!?

public static class Snippet
{
	public static void tryJson(System.String jsonString)
	{
		DebugLogger.Logger.Log("Starting JSON deserialization attempts.");
		try {
			DataTable table = JsonConvert.DeserializeObject<DataTable>(jsonString);
			DebugLogger.Logger.Log(table.TableName);
			table.TableName = "product";

			//DebugLogger.Logger.Log("Column count");
			//DebugLogger.Logger.Log(table.Columns.Count.ToString());
			//DebugLogger.Logger.Log("Row info: " + table.Rows[4][1]);

			MagicSqlConnector.MagicSqlConnector.DataTableIntoDb(table);
			// Try putting data back to the SQL DB.
			//MagicSqlConnector.MagicSqlConnector.UpdateProductName("somethinghappened");
		}
		catch (Exception e) {
			DebugLogger.Logger.Log(e.Message);
		}
		DebugLogger.Logger.Log("Finished JSON deserialization attempts.");
	}

}

using System;
using DebugLogger;
using System.Data;

public static class Snippet
{
	public static void func(System.Data.DataTable dataTable)
	{
		DebugLogger.Logger.Log("-- Starting dotnet");
		try {
			// Basic access / sanity checks
			bool isNull = (dataTable == null);
			DebugLogger.Logger.Log("Is it null? " + isNull.ToString());
			DebugLogger.Logger.Log("No of columns: " + dataTable.Columns.Count); // Expected to be 2.
			DebugLogger.Logger.Log("First column: " + dataTable.Columns[0].ToString()); // v_productId
			DebugLogger.Logger.Log("Some other info: " + dataTable.Rows[4][0]);

			// Try to get the 2nd column
			try {
				DebugLogger.Logger.Log("2nd column: " + dataTable.Columns[1].ToString()); // v_productName
			}
			catch (Exception e) {
				DebugLogger.Logger.Log("Couldn't access the 2nd column.");
				DebugLogger.Logger.Log(e.ToString().Substring(0,30));
			}

			// Iterate columns, see what we get
			foreach (DataColumn col in dataTable.Columns) {
				DebugLogger.Logger.Log(col.DataType.ToString());
			}
		}
		catch (Exception e) {
			DebugLogger.Logger.Log("General exception occured.");
			DebugLogger.Logger.Log(e.ToString());
		}
		DebugLogger.Logger.Log("Finished dotnet.");

	}

}
